+		static {
+			byte lowest = F.id;
+			byte highest = F.id;
+			for (Tone tone : Tone.values()) {
+				byte id = tone.id;
+				tones.put(id, tone);
+				if (id < lowest) {
+					lowest = id;
+				}
+				if (tone.isSharpable()) {
+					id++;
+					tones.put(id, tone);
+				}
+				if (id > highest) {
+					highest = id;
+				}
+			}
+
+			TONES_COUNT = (byte) (highest - lowest + 1);
+			tones.put((byte) (TONES_COUNT - 1), F);
+		}
